import{_ as o,C as n,o as a,c as s,a2 as e,b as i,w as l,a as d,E as g,a3 as h}from"./chunks/framework.CZGNF-7T.js";const p=JSON.parse('{"title":"로드맵 (Roadmap)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/roadmap.md","filePath":"work-manage/roadmap.md","lastUpdated":1788455979000}'),A={name:"work-manage/roadmap.md"};function E(c,t,B,u,m,C){const r=n("Mermaid");return a(),s("div",null,[t[1]||(t[1]=e('<h1 id="로드맵-roadmap" tabindex="-1">로드맵 (Roadmap) <a class="header-anchor" href="#로드맵-roadmap" aria-label="Permalink to &quot;로드맵 (Roadmap)&quot;">​</a></h1><blockquote><p><strong>로드맵</strong> 페이지는 워크스페이스의 주요 마일스톤(단계/버전)별 진행 상황을 시각적으로 모니터링하고 관리하는 협업 대시보드입니다. 프로젝트를 여러 마일스톤으로 나누어 각 목표 대비 현재 어느 정도 도달했는지 실시간으로 파악할 수 있습니다.</p></blockquote><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><p>워크스페이스의 전체 일정을 큰 단위(단계)로 나누어 관리합니다. 각 단계에는 여러 개의 **<a href="/work-manage/issue.html">업무(Issue)</a>**가 연결되어 있으며, 이 업무들의 완료 상태와 진척률이 집계되어 해당 단계의 전체 진행도를 결정합니다.</p>',4)),(a(),i(h,null,{default:l(()=>[g(r,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%EB%A7%88%EC%9D%BC%EC%8A%A4%ED%86%A4%EC%A7%91%EA%B3%84%20%5B%22%EB%8B%A8%EA%B3%84(%EB%A7%88%EC%9D%BC%EC%8A%A4%ED%86%A4)%20%EC%A7%84%ED%96%89%EB%A5%A0%20%EC%A7%91%EA%B3%84%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%EC%97%85%EB%AC%B4%20%23101%20(%EC%A7%84%EC%B2%99%EB%A5%A0%20100%25)%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%EC%97%85%EB%AC%B4%20%23102%20(%EC%A7%84%EC%B2%99%EB%A5%A0%2050%25)%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22%EC%97%85%EB%AC%B4%20%23103%20(%EC%A7%84%EC%B2%99%EB%A5%A0%200%25)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20A%20%26%20B%20%26%20C%20--%3E%20D%5B%22%F0%9F%93%8A%20%EB%8B%A8%EA%B3%84%20%ED%8F%89%EA%B7%A0%20%EC%A7%84%ED%96%89%EB%A5%A0%3A%2050%25%3Cbr%3E(CProgress%20%EB%B0%94%20%EC%8B%9C%EA%B0%81%ED%99%94)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%F0%9F%8E%AF%20%EB%A1%9C%EB%93%9C%EB%A7%B5%20%EC%A0%84%EC%B2%B4%20%EB%AA%A9%ED%91%9C%20%EB%8B%AC%EC%84%B1%EB%8F%84%20%EB%B0%98%EC%98%81%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="_2-주요-기능-안내" tabindex="-1">2. 주요 기능 안내 <a class="header-anchor" href="#_2-주요-기능-안내" aria-label="Permalink to &quot;2. 주요 기능 안내&quot;">​</a></h2><h3 id="📊-단계별-진행도-및-통계-시각화" tabindex="-1">📊 단계별 진행도 및 통계 시각화 <a class="header-anchor" href="#📊-단계별-진행도-및-통계-시각화" aria-label="Permalink to &quot;📊 단계별 진행도 및 통계 시각화&quot;">​</a></h3><ul><li><strong>진행률 프로그레스 바</strong>: 각 단계 카드 상단에 연결된 모든 업무의 평균 완료율(<code>done_ratio</code>)이 직관적인 녹색 게이지 그래프로 표시됩니다.</li><li><strong>상태 요약 링크</strong>: <ul><li><strong><code>업무 N 건</code></strong>: 해당 단계에 할당된 전체 업무 수를 나타내며, 클릭 시 해당 업무 목록으로 즉시 이동합니다.</li><li><strong><code>N 건 완료 / N 건 진행 중</code></strong>: 완료된 업무 건수와 미완료 업무 건수를 분리 표시하며, 클릭 시 해당 조건의 업무 필터 목록으로 연결됩니다.</li></ul></li></ul><h3 id="🔍-단계-상세-정보-및-업무-목록" tabindex="-1">🔍 단계 상세 정보 및 업무 목록 <a class="header-anchor" href="#🔍-단계-상세-정보-및-업무-목록" aria-label="Permalink to &quot;🔍 단계 상세 정보 및 업무 목록&quot;">​</a></h3><ul><li><strong>단계 상세 이동</strong>: 단계 제목을 클릭하면 해당 마일스톤의 상세 화면으로 이동합니다.</li><li><strong>업무 목록 테이블</strong>: 단계에 배정된 업무들의 번호, 유형(트래커), 제목, 담당자, 진척률이 표시되며, 완료된 업무는 취소선으로 구분됩니다.</li></ul><h3 id="🧭-우측-사이드바-로드맵-설정-및-단계-색인" tabindex="-1">🧭 우측 사이드바: 로드맵 설정 및 단계 색인 <a class="header-anchor" href="#🧭-우측-사이드바-로드맵-설정-및-단계-색인" aria-label="Permalink to &quot;🧭 우측 사이드바: 로드맵 설정 및 단계 색인&quot;">​</a></h3><p>화면 우측 사이드바를 통해 복잡한 마일스톤 목록을 빠르게 제어하고 탐색할 수 있습니다.</p><ul><li><strong>유형(Tracker)별 필터링</strong>: <ul><li>결함, 기능, 지원 등 특정 업무 유형만 체크박스로 선택하여, 해당 유형의 업무들로만 진행도를 재계산하고 목록을 필터링할 수 있습니다.</li></ul></li><li><strong>완료된 단계 포함 토글</strong>: <ul><li><code>완료된 단계 포함</code> 체크박스를 통해 이미 종료된 단계를 목록에 함께 표시하거나 숨겨 현재 진행 중인 마일스톤에 집중할 수 있습니다.</li></ul></li><li><strong>단계 색인(목차) 및 원클릭 스크롤</strong>: <ul><li>우측 패널 하단에 모든 단계의 이름과 진척률(<code>%</code>)이 목록으로 요약 제공됩니다.</li><li>특정 단계를 클릭하면 메인 화면에서 해당 단계 카드로 부드럽게 자동 스크롤(<code>Smooth Scroll</code>)되며 하이라이트 테두리가 표시됩니다.</li></ul></li></ul><h3 id="⚙️-단계-관리-및-권한-통제" tabindex="-1">⚙️ 단계 관리 및 권한 통제 <a class="header-anchor" href="#⚙️-단계-관리-및-권한-통제" aria-label="Permalink to &quot;⚙️ 단계 관리 및 권한 통제&quot;">​</a></h3><ul><li><strong>새 단계 추가</strong>: 우측 상단의 <strong>[새 단계]</strong> 버튼을 클릭하여 새로운 마일스톤(이름, 설명, 시작일, 종료일)을 정의합니다. (관리자 권한 필요)</li><li><strong>단계 정보 수정</strong>: 각 단계 헤더 우측의 연필 아이콘(<i class="mdi mdi-pencil"></i>)을 클릭하여 단계 속성을 편집할 수 있습니다.</li><li><strong>설정 연동</strong>: 우측 상단의 더보기(<code>...</code>) 아이콘을 통해 <a href="/work-manage/settings.html">워크스페이스 설정 &gt; 단계</a> 메뉴로 원클릭 이동하여 전체 마일스톤을 일괄 관리할 수 있습니다.</li></ul><h2 id="_3-단계-상태-status-체계" tabindex="-1">3. 단계 상태(Status) 체계 <a class="header-anchor" href="#_3-단계-상태-status-체계" aria-label="Permalink to &quot;3. 단계 상태(Status) 체계&quot;">​</a></h2><p>각 단계는 목표 달성 과정에 따라 3가지 상태로 관리되며 카드 상단에 색상 배지로 구분됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">상태</th><th style="text-align:center;">배지 색상</th><th style="text-align:left;">설명</th><th style="text-align:center;">업무 추가 가능 여부</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>진행 중 (Open)</strong></td><td style="text-align:center;">파란색</td><td style="text-align:left;">현재 활발히 목표가 진행 중인 단계</td><td style="text-align:center;">O</td></tr><tr><td style="text-align:left;"><strong>잠김 (Locked)</strong></td><td style="text-align:center;">빨간색</td><td style="text-align:left;">기한 도래 또는 잠정 동결되어 신규 업무 배정이 제한되고 진행만 추적하는 단계</td><td style="text-align:center;">X</td></tr><tr><td style="text-align:left;"><strong>닫힘 (Closed)</strong></td><td style="text-align:center;">초록색</td><td style="text-align:left;">모든 업무가 완수되어 공식 종료된 마일스톤</td><td style="text-align:center;">X</td></tr></tbody></table><h2 id="_4-로드맵-메뉴-노출-조건" tabindex="-1">4. 로드맵 메뉴 노출 조건 <a class="header-anchor" href="#_4-로드맵-메뉴-노출-조건" aria-label="Permalink to &quot;4. 로드맵 메뉴 노출 조건&quot;">​</a></h2><p>워크스페이스 상단 탭에서 <strong>&#39;로드맵&#39;</strong> 메뉴가 보이지 않는다면 다음 사항을 확인하세요.</p><ul><li><strong>등록된 단계(버전) 없음</strong>: 워크스페이스에 등록된 단계가 하나도 없을 경우 로드맵 메뉴는 자동으로 숨겨집니다.</li><li><strong>활성화 방법</strong>: <a href="/work-manage/settings.html">설정 &gt; 단계</a> 메뉴에서 새로운 단계를 1개 이상 등록하면 상단 메뉴에 &#39;로드맵&#39; 탭이 즉시 나타납니다.</li></ul>',16))])}const f=o(A,[["render",E]]);export{p as __pageData,f as default};
